// TEST MODE PAIRS (seules les paires V2 sont déployées en testnet)
export const TEST_PAIRS: PairConfig[] = ETHEREUM_TESTNET_PAIRS.map(pool => {
    // Determine stablecoin position based on stables in the token names.
    const stables = ['USDC', 'USDT', 'DAI', 'USD1'];
    let stablePos = 0; // Default to 0 (ETH pair)

    if (stables.some(s => pool.name?.includes(s))) {
        // However, if it's paired with WETH, and it's a stablecoin we want to verify via ETH loop, we could set 0.
        // But for direct stablecoin pairs like USDC/WETH, we can treat them as stablecoin directly.
        // BUT if we want to treat USD1/WETH as an ETH pair to correctly price USD1 via WETH->USDC : 
        if (pool.name?.includes('WETH') && pool.name?.includes('USD1')) {
            stablePos = 0; // Force ETH routing for USD1/WETH
        } else if (pool.name?.startsWith('USDC') || pool.name?.startsWith('USDT') || pool.name?.startsWith('DAI') || pool.name?.startsWith('USD1')) {
            stablePos = 1;
        } else {
            stablePos = 2; // the stable is usually token1 if it's the quote
        }
    } else if (pool.name?.includes('WETH')) {
        // If no stablecoin but it includes WETH (like WETH/ONDO), it's definitely an ETH pair
        stablePos = 0;
    } else {
        stablePos = 2; // Default fallback
    }

    const parts = pool.name?.split('/') || [];
    const sym0 = parts[0];
    const sym1 = parts[1];

    let assetAddr = pool.token0;
    let baseAddr = pool.token1;

    const getQuotePriority = (sym: string) => {
        if (stables.includes(sym)) return 2;
        if (sym === 'WETH') return 1;
        return 0;
    };

    const priority0 = getQuotePriority(sym0);
    const priority1 = getQuotePriority(sym1);

    if (priority0 > priority1) {
        // sym0 is the quote, sym1 is the asset
        assetAddr = pool.token1;
        baseAddr = pool.token0;
    } else {
        // sym1 is the quote, sym0 is the asset
        assetAddr = pool.token0;
        baseAddr = pool.token1;
    }

    return {
        name: pool.name ? `${pool.name} (${pool.version.toUpperCase()})` : 'Unknown',
        address: pool.address,
        tokenAddress: assetAddr,
        baseTokenAddress: baseAddr,
        version: pool.version.toUpperCase() as 'V2' | 'V3',
        stablecoinPosition: stablePos
    };
});

